function currentExtractAttempt() {
  try {
    if ($('Code — Decide Extract Retry').isExecuted) {
      const n = $('Code — Decide Extract Retry').first().json.extractAttempt;
      if (typeof n === 'number' && n >= 1) return n;
    }
  } catch (_) { /* Decide never ran this execution */ }
  return 1;
}

const extractAttempt = currentExtractAttempt();
const raw = $input.first().json.content?.[0]?.text ?? $input.first().json.text ?? '';

if (!raw.trim()) {
  return [{ json: { parseOk: false, errors: ['Empty response from Claude'], stage: 'parse', extractAttempt } }];
}

try {
  const data = JSON.parse(raw.trim());
  if (typeof data !== 'object' || data === null || Array.isArray(data)) {
    return [{ json: { parseOk: false, errors: ['Parsed JSON must be an object'], stage: 'parse', extractAttempt } }];
  }
  return [{ json: { parseOk: true, data, extractAttempt } }];
} catch (error) {
  return [{ json: { parseOk: false, errors: [`Invalid JSON: ${error.message}`], stage: 'parse', extractAttempt } }];
}

// Receipt schema (required): merchant (string), date (YYYY-MM-DD), total (number), line_items (non-empty array)
const data = $input.first().json.data;
const errors = [];
const extractAttempt = $input.first().json.extractAttempt ?? 1;

function normalizeDate(value) {
  if (typeof value !== 'string' || !value.trim()) {
    errors.push('date is required');
    return null;
  }
  const trimmed = value.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
    return trimmed;
  }
  const match = trimmed.match(/^(\d{1,2})[./](\d{1,2})[./](\d{4})$/);
  if (match) {
    const [, day, month, year] = match;
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }
  errors.push(`date could not be normalized: ${trimmed}`);
  return null;
}

function normalizeTotal(value) {
  if (typeof value === 'number' && !Number.isNaN(value)) {
    return value;
  }
  if (typeof value === 'string' && value.trim()) {
    const parsed = parseFloat(value.trim().replace(',', '.'));
    if (!Number.isNaN(parsed)) {
      return parsed;
    }
  }
  errors.push('total must be a number');
  return null;
}

function normalizeLineItems(value) {
  if (!Array.isArray(value) || value.length === 0) {
    errors.push('line_items must be a non-empty array');
    return [];
  }
  return value;
}

let merchant = data.merchant;
if (typeof merchant !== 'string' || !merchant.trim()) {
  errors.push('merchant is required');
  merchant = null;
} else {
  merchant = merchant.trim();
}

const date = normalizeDate(data.date);
const total = normalizeTotal(data.total);
const lineItems = normalizeLineItems(data.line_items);

if (errors.length > 0) {
  return [{ json: { valid: false, errors, stage: 'validation', extractAttempt } }];
}

return [{
  json: {
    valid: true,
    receipt: {
      merchant,
      date,
      total,
      line_items: lineItems,
    },
  },
}];

const { createHash } = require('crypto');

const input = $input.first().json;
const receipt = {
  merchant: input.merchant,
  date: input.date,
  total: input.total,
  line_items: input.line_items,
};

function merchantSlug(name) {
  return name
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40) || 'unknown';
}

function canonicalReceipt(r) {
  const lineItems = [...r.line_items]
    .sort((a, b) => a.description.localeCompare(b.description))
    .map((item) => ({
      category: item.category,
      description: item.description,
      price: item.price,
      quantity: item.quantity,
    }));
  return {
    date: r.date,
    line_items: lineItems,
    merchant: r.merchant,
    total: r.total,
  };
}

const canonical = canonicalReceipt(receipt);
const canonicalJson = JSON.stringify(canonical);
const contentHash = createHash('sha256').update(canonicalJson).digest('hex').slice(0, 8);
const slug = merchantSlug(receipt.merchant);
const filename = `${receipt.date}_${slug}_${contentHash}.json`;
const filePath = `/home/node/.n8n-files/receipts/${filename}`;
const now = new Date().toISOString();
const output = {
  date: canonical.date,
  extracted_at: now,
  categorized_at: now,
  line_items: canonical.line_items,
  merchant: canonical.merchant,
  total: canonical.total,
};
const fileBody = JSON.stringify(output, null, 2) + '\n';

return [{
  json: {
    ...output,
    persistedFilename: filename,
    persistedPath: filePath,
    contentHash,
  },
  binary: {
    data: {
      data: Buffer.from(fileBody, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: filename,
    },
  },
}];

const persistedFilename = $('Code — Build Receipt File').first().json.persistedFilename;
const health = $('HTTP Request — GET Health').first().json;
const coverage = $input.first().json;
const loadedFiles = coverage.loaded_files ?? [];

return [{
  json: {
    api_status: health.status,
    data_path: coverage.data_path,
    files_loaded: coverage.files_loaded,
    logical_receipt_count: coverage.logical_receipt_count,
    loaded_files: loadedFiles,
    persistedFilename,
    persistedInCoverage: loadedFiles.includes(persistedFilename),
  },
}];

const summary = $input.first().json;

return [{
  json: {
    analytics_endpoint: 'summary',
    analytics_preset: 'last_N_days',
    n_days: 90,
    period_label: summary.period_label,
    start_date: summary.start_date,
    end_date: summary.end_date,
    total_spend: summary.total_spend,
    top_categories: summary.top_categories ?? [],
    by_category: summary.by_category ?? [],
    summary_facts: summary.summary_facts ?? [],
  },
}];

