const DEMO_QUESTION = 'How much did I spend on food last month?';
const response = $input.first().json;
const query = response.query ?? null;
const analytics = query?.analytics ?? null;

return [{
  json: {
    demo: true,
    demo_question: DEMO_QUESTION,
    answer: response.answer ?? null,
    intent: query?.intent ?? null,
    categories: analytics?.categories ?? null,
    time_range: analytics?.time_range ?? null,
    query_warnings: query?.warnings ?? [],
    meta: response.meta ?? null,
  },
}];

function currentCategorizeAttempt() {
  try {
    if ($('Code — Decide Categorize Retry').isExecuted) {
      const n = $('Code — Decide Categorize Retry').first().json.categorizeAttempt;
      if (typeof n === 'number' && n >= 1) return n;
    }
  } catch (_) { /* Decide never ran this execution */ }
  return 1;
}

const categorizeAttempt = currentCategorizeAttempt();
const raw = $input.first().json.content?.[0]?.text ?? $input.first().json.text ?? '';

if (!raw.trim()) {
  return [{ json: { parseOk: false, errors: ['Empty response from Claude'], stage: 'parse', categorizeAttempt } }];
}

try {
  const data = JSON.parse(raw.trim());
  if (typeof data !== 'object' || data === null || Array.isArray(data)) {
    return [{ json: { parseOk: false, errors: ['Parsed JSON must be an object'], stage: 'parse', categorizeAttempt } }];
  }
  return [{ json: { parseOk: true, data, categorizeAttempt } }];
} catch (error) {
  return [{ json: { parseOk: false, errors: [`Invalid JSON: ${error.message}`], stage: 'parse', categorizeAttempt } }];
}

// Categorization schema: M2 receipt fields + category on each line_items[] entry
const ALLOWED_CATEGORIES = new Set(['food', 'snacks', 'drinks', 'household', 'other']);

const data = $input.first().json.data;
const errors = [];
const categorizeAttempt = $input.first().json.categorizeAttempt ?? 1;

let merchant = data.merchant;
if (typeof merchant !== 'string' || !merchant.trim()) {
  errors.push('merchant is required');
  merchant = null;
} else {
  merchant = merchant.trim();
}

let date = data.date;
if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date.trim())) {
  errors.push('date must be YYYY-MM-DD');
  date = null;
} else {
  date = date.trim();
}

let total = data.total;
if (typeof total !== 'number' || Number.isNaN(total)) {
  errors.push('total must be a number');
  total = null;
}

const lineItems = [];
if (!Array.isArray(data.line_items) || data.line_items.length === 0) {
  errors.push('line_items must be a non-empty array');
} else {
  for (let i = 0; i < data.line_items.length; i++) {
    const item = data.line_items[i];
    const label = `line_items[${i}]`;
    if (typeof item !== 'object' || item === null || Array.isArray(item)) {
      errors.push(`${label} must be an object`);
      continue;
    }
    if (typeof item.description !== 'string' || !item.description.trim()) {
      errors.push(`${label}.description is required`);
    }
    if (typeof item.quantity !== 'number' || Number.isNaN(item.quantity)) {
      errors.push(`${label}.quantity must be a number`);
    }
    if (typeof item.price !== 'number' || Number.isNaN(item.price)) {
      errors.push(`${label}.price must be a number`);
    }
    if (typeof item.category !== 'string' || !item.category.trim()) {
      errors.push(`${label}.category is required`);
    } else if (!ALLOWED_CATEGORIES.has(item.category.trim())) {
      errors.push(`${label}.category must be one of: food, snacks, drinks, household, other (got "${item.category}")`);
    }
    lineItems.push(item);
  }
}

if (errors.length > 0) {
  return [{ json: { valid: false, errors, stage: 'validation', categorizeAttempt } }];
}

return [{
  json: {
    valid: true,
    receipt: {
      merchant,
      date,
      total,
      line_items: lineItems,
    },
  },
}];

const MAX_EXTRACT_ATTEMPTS = 3; // 1 initial + 2 retries — keep in sync with docs

const incoming = $input.first().json;
const errors = incoming.errors ?? ['Unknown extract failure'];
const stage = incoming.stage ?? 'validation';
const completed = incoming.extractAttempt ?? 1;

if (completed >= MAX_EXTRACT_ATTEMPTS) {
  return [{ json: { shouldRetry: false, valid: false, errors, stage } }];
}

const text = $('Extract from File — PDF to Text').first().json.text;
if (!text || !String(text).trim()) {
  return [{
    json: {
      shouldRetry: false,
      valid: false,
      errors: [...errors, 'Missing receipt text for retry'],
      stage,
    },
  }];
}

return [{
  json: {
    shouldRetry: true,
    text,
    extractAttempt: completed + 1,
    lastErrors: errors,
    lastStage: stage,
  },
}];

const MAX_CATEGORIZE_ATTEMPTS = 3; // 1 initial + 2 retries — keep in sync with docs

const incoming = $input.first().json;
const errors = incoming.errors ?? ['Unknown categorization failure'];
const stage = incoming.stage ?? 'validation';
const completed = incoming.categorizeAttempt ?? 1;

if (completed >= MAX_CATEGORIZE_ATTEMPTS) {
  return [{ json: { shouldRetry: false, valid: false, errors, stage } }];
}

const receipt = $('Set — Normalized Receipt').first().json;
if (!receipt?.merchant || !Array.isArray(receipt.line_items)) {
  return [{
    json: {
      shouldRetry: false,
      valid: false,
      errors: [...errors, 'Missing normalized receipt for retry'],
      stage,
    },
  }];
}

return [{
  json: {
    shouldRetry: true,
    merchant: receipt.merchant,
    date: receipt.date,
    total: receipt.total,
    line_items: receipt.line_items,
    categorizeAttempt: completed + 1,
    lastErrors: errors,
    lastStage: stage,
  },
}];

const SAMPLE_ROOT = '/home/node/.n8n-files/samples';
const ALLOWLIST = {
  '03-small': `${SAMPLE_ROOT}/03-small.pdf`,
  '01-food-homedeco': `${SAMPLE_ROOT}/01-food-homedeco.pdf`,
  '02-vegetables-weighted': `${SAMPLE_ROOT}/02-vegetables-weighted.pdf`,
  '04-article-discount': `${SAMPLE_ROOT}/04-article-discount.pdf`,
  '05-demo-basket': `${SAMPLE_ROOT}/05-demo-basket.pdf`,
};
const DEFAULT_SAMPLE = '03-small';

const item = $input.first().json;
// Webhook executions always include headers; Manual Trigger does not.
const entrySource = item.headers !== undefined ? 'webhook' : 'manual';

let sample = DEFAULT_SAMPLE;
if (entrySource === 'webhook') {
  const body = item.body && typeof item.body === 'object' ? item.body : {};
  const raw = body.sample ?? item.sample;
  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
    sample = String(raw).trim();
  }
}

const filePath = ALLOWLIST[sample];
if (!filePath) {
  const allowed = Object.keys(ALLOWLIST).join(', ');
  return [{
    json: {
      sampleAllowed: false,
      ok: false,
      error: 'unknown_sample',
      message: `Unknown sample id '${sample}'. Allowed: ${allowed}`,
      sample,
      entrySource,
      httpStatus: 400,
    },
  }];
}

return [{
  json: {
    sampleAllowed: true,
    ok: true,
    sample,
    filePath,
    entrySource,
  },
}];

const built = $('Code — Build Receipt File').first().json;
const entrySource = $('Code — Resolve Sample Path').first().json.entrySource;

return [{
  json: {
    ok: true,
    persistedFilename: built.persistedFilename,
    merchant: built.merchant,
    date: built.date,
    total: built.total,
    entrySource,
    httpStatus: 200,
  },
}];

const entrySource = $('Code — Resolve Sample Path').first().json.entrySource;
const err = $input.first().json;

return [{
  json: {
    ok: false,
    error: 'pipeline_failed',
    stage: err.stage ?? 'unknown',
    errors: err.errors ?? [],
    entrySource,
    httpStatus: 422,
  },
}];
